                  placeholder="Write Markdown here…"
                  spellCheck
                  className="h-[45dvh] resize-none border-b border-(--line) bg-(--bg) p-4 font-mono text-sm leading-relaxed outline-none md:h-full md:border-r md:border-b-0"
                />
