    const t = setTimeout(() => {
      dirty.current = false
      saved.current = notes
      setSaveState(saveNotes(localStorage, notes) ? 'saved' : 'error')
    }, 400)
    return () => clearTimeout(t)
  }, [notes])
  useEffect(() => {
    const flush = () => {
      if (dirty.current) {
        dirty.current = false
